// Deterministic combined-bundle builder v2.4 (dedup). Rebuilds the generated bundle from the
// registry's ACTIVE bundles only, running the guard in its safe default (auto-baseline)
// mode before and after generation.
// v2.4: the combined file is written by serializeCombinedDedup (lib-combined-dedup.mjs):
// shared chunks/figures emitted once, every bundle rebuilt and sha256-verified at import.
// Usage: node build-bcba-bundle.mjs <root> [--out <generated-file-path>]
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { loadBundles, sha256 } from './lib-bundles.mjs';
import { serializeCombinedDedup } from './lib-combined-dedup.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const root = path.resolve(argv[0] || '.');
const outIdx = argv.indexOf('--out');
const outOpt = outIdx > -1 ? argv[outIdx + 1] : null;
const guardArgs = [path.join(here, 'check-retained-bcba.mjs'), root];
for (const f of ['--local-head-ok', '--offline']) if (argv.includes(f)) guardArgs.push(f); // explicit local escapes (never the deploy build)
if (outOpt) guardArgs.push('--generated', path.resolve(outOpt));
// Pre-check (registry/bundles/figures + auto history proof); the generated file may not exist yet.
execFileSync('node', [...guardArgs, '--allow-missing-generated'], { stdio: 'inherit' });

const reg = JSON.parse(fs.readFileSync(path.join(root, 'release-retention', 'registry.json')));
const active = reg.bundles.filter(b => b.status === 'active');
if (!active.length) throw Error('no active bundles; refusing to generate an empty qualified set');
const objs = [];
for (const b of active) {
  const p = path.join(root, 'release-retention', b.file);
  const onDisk = fs.readFileSync(p);
  if (sha256(onDisk) !== b.sha256) throw Error('ABORT: ' + b.file + ' bytes do not match registry sha256');
  const loaded = await loadBundles(pathToFileURL(p).href);
  if (loaded.length !== 1) throw Error('ABORT: ' + b.file + ' must export exactly one bundle');
  // (v2.4: no whole-source re-serialization check - retention authority is the registry sha256
  // above plus the post-write deepStrictEqual against each loaded original below.)
  objs.push(loaded[0]);
}
const header = `// GENERATED by scripts/build-bcba-bundle.mjs v2.4 (dedup) from release-retention/registry.json - do not edit.\n// Active source files (immutable, hash-listed): ${active.map(a=>a.file).join(', ')}\n// Withdrawn entries are excluded and retained under release-retention/ for explicit-unavailable serving.\n// Shared chunks/figures are emitted once; every bundle is rebuilt and sha256-verified at import.\n`;
const out = serializeCombinedDedup(objs, header);
const outPath = outOpt ? path.resolve(outOpt) : path.join(root, 'supabase', 'functions', 'bcba-program', 'generated-bcba-bundle.mjs');
fs.mkdirSync(path.dirname(outPath), { recursive: true });
// v2.4 atomic write: generate to a temp file beside the target, prove it, THEN rename.
// The deploy-dir file is never replaced by an unproven file; on any failure the temp is removed.
const tmpPath = outPath + '.tmp-' + process.pid + '.mjs';
try {
  fs.writeFileSync(tmpPath, out);
  // Post-write proof on the temp: imports, and every active bundle deep-equals its source object, in order.
  const gen = await loadBundles(pathToFileURL(tmpPath).href);
  if (gen.length !== objs.length) throw Error('generated element count mismatch');
  const { deepStrictEqual } = await import('node:assert/strict');
  for (let i = 0; i < objs.length; i++) deepStrictEqual(gen[i], objs[i]);
  // Independent pin-keyed proof (not index-only).
  const byPin = new Map(gen.map(o => [o.policyId + '|' + o.manifestVersion, o]));
  if (byPin.size !== gen.length) throw Error('duplicate member pin in generated output');
  for (const o of objs) deepStrictEqual(byPin.get(o.policyId + '|' + o.manifestVersion), o);
  // Full (strengthened) guard against the TEMP file before it can replace anything.
  const tmpGuardArgs = guardArgs.filter((a, i, arr) => a !== '--generated' && arr[i - 1] !== '--generated');
  execFileSync('node', [...tmpGuardArgs, '--generated', tmpPath], { stdio: 'inherit' });
  fs.renameSync(tmpPath, outPath); // atomic on the same filesystem
} catch (e) {
  try { fs.rmSync(tmpPath, { force: true }); } catch {}
  throw e;
}
// Post-check: full guard on the final path.
execFileSync('node', guardArgs.includes('--generated') ? guardArgs : [...guardArgs, '--generated', outPath], { stdio: 'inherit' });
const size = Buffer.byteLength(out);
console.log('WROTE ' + outPath + ' (' + objs.length + ' active bundle(s), deep-equal verified; generated source ' + size + ' bytes, 5 MiB margin ' + (5242880 - size) + ' - NOT the final bundled function size)');

